/**
 * HUNTING - Wachhalter (Screen WakeLock & iOS Silent Video Loop)
 *
 * Verhindert das Abschalten oder Dimmen des Smartphone-Bildschirms während
 * der Jagd. Nutzt eine duale Strategie:
 *
 * 1. Strategie A (Standard): W3C Screen Wake Lock API (`navigator.wakeLock`).
 * 2. Strategie B (iOS/Fallback): 1x1 stumme, unsichtbare Video-Endlosschleife
 *    (NoSleep-Prinzip). iOS Safari geht bei aktiver Inline-Videowiedergabe
 *    niemals in den Ruhezustand.
 *
 * Inklusive:
 * - Automatisches Entsperren über Nutzergesten (iOS Autoplay Restriction Unlock)
 * - Automatischer Wiederaufbau bei Tab-Wechsel (visibilitychange & focus)
 * - Zero Dependencies, 100% autark über integrierte Base64-Video-URIs
 */

// Minimale 1x1 stumme Videodateien (VP8 WebM und H.264 Baseline MP4)
const WEBM_DATA_URI =
  "data:video/webm;base64,";

const MP4_DATA_URI =
  "data:video/mp4;base64,";

export interface WachhalterStatus {
  istAktiv: boolean;
  wakeLockAktiv: boolean;
  videoAktiv: boolean;
  wakeLockUnterstuetzt: boolean;
}

export type WachhalterListener = (status: WachhalterStatus) => void;

export class Wachhalter {
  public istAktiv = false;
  public wakeLockAktiv = false;
  public videoAktiv = false;
  public wakeLockUnterstuetzt = false;

  private wakeLockSentinel: any = null;
  private videoElement: HTMLVideoElement | null = null;
  private gestureListenerGebunden = false;
  private statusListeners: Set<WachhalterListener> = new Set();

  constructor() {
    if (typeof window !== "undefined") {
      this.wakeLockUnterstuetzt = "wakeLock" in navigator;

      // Tab-Wechsel-Resilienz: Wenn die App wieder in den Vordergrund tritt,
      // müssen sowohl WakeLock als auch Video sofort reaktiviert werden.
      document.addEventListener("visibilitychange", () => {
        if (document.visibilityState === "visible" && this.istAktiv) {
          this.reaktiviere();
        }
      });

      // Zusätzlicher Schutz bei Fensterfokus (z. B. nach Kontrollzentrum / Benachrichtigungsleiste)
      window.addEventListener("focus", () => {
        if (this.istAktiv && (!this.wakeLockAktiv || !this.videoAktiv)) {
          this.reaktiviere();
        }
      });
    }
  }

  /**
   * Aktiviert den Wachhalter (Screen WakeLock + stumme Video-Schleife)
   */
  public async aktivieren(): Promise<boolean> {
    if (typeof window === "undefined") return false;

    this.istAktiv = true;
    this.initialisiereGestenEntsperrung();

    let wakeLockErfolg = false;
    let videoErfolg = false;

    // Strategie A: Native Screen Wake Lock API
    try {
      wakeLockErfolg = await this.anfordernWakeLock();
    } catch {
      wakeLockErfolg = false;
    }

    // Strategie B: Video-Endlosschleife (NoSleep Trick für iOS Safari & WebViews)
    try {
      videoErfolg = await this.starteVideo();
    } catch {
      videoErfolg = false;
    }

    this.benachrichtigeStatus();
    return wakeLockErfolg || videoErfolg || this.istAktiv;
  }

  /**
   * Deaktiviert den Wachhalter und gibt alle Systemressourcen frei
   */
  public async deaktivieren(): Promise<void> {
    this.istAktiv = false;

    // Wake Lock freigeben
    await this.gebeWakeLockFrei();

    // Video pausieren und aufräumen
    this.stoppeVideo();

    this.entferneGestenEntsperrung();
    this.benachrichtigeStatus();
  }

  /**
   * Schaltet den Wachhalter um (Toggle)
   */
  public async toggle(): Promise<boolean> {
    if (this.istAktiv) {
      await this.deaktivieren();
      return false;
    } else {
      return await this.aktivieren();
    }
  }

  /**
   * Reaktiviert beide Mechanismen nach Visibility-Change oder Fokusverlust
   */
  private async reaktiviere(): Promise<void> {
    if (!this.istAktiv) return;

    if (this.wakeLockUnterstuetzt && !this.wakeLockAktiv) {
      await this.anfordernWakeLock().catch(() => {});
    }

    if (!this.videoAktiv) {
      await this.starteVideo().catch(() => {});
    }

    this.benachrichtigeStatus();
  }

  /**
   * Strategie A: W3C Screen Wake Lock API
   */
  private async anfordernWakeLock(): Promise<boolean> {
    if (!this.wakeLockUnterstuetzt) return false;

    try {
      if (this.wakeLockSentinel && !this.wakeLockSentinel.released) {
        this.wakeLockAktiv = true;
        return true;
      }

      const sentinel = await (navigator as any).wakeLock.request("screen");
      this.wakeLockSentinel = sentinel;
      this.wakeLockAktiv = true;

      sentinel.addEventListener("release", () => {
        this.wakeLockSentinel = null;
        this.wakeLockAktiv = false;
        this.benachrichtigeStatus();

        // Falls noch aktiv (z. B. nach kurzem Screen-Dimming oder Notification), sofort reaktivieren
        if (this.istAktiv && document.visibilityState === "visible") {
          setTimeout(() => {
            if (this.istAktiv && !this.wakeLockAktiv) {
              this.anfordernWakeLock().catch(() => {});
            }
          }, 500);
        }
      });

      return true;
    } catch (err) {
      this.wakeLockAktiv = false;
      return false;
    }
  }

  private async gebeWakeLockFrei(): Promise<void> {
    if (this.wakeLockSentinel) {
      try {
        await this.wakeLockSentinel.release();
      } catch {}
      this.wakeLockSentinel = null;
    }
    this.wakeLockAktiv = false;
  }

  /**
   * Strategie B: Stumme 1x1 Video-Endlosschleife (iOS Safari & WebKit Hack)
   */
  private async starteVideo(): Promise<boolean> {
    if (typeof document === "undefined") return false;

    if (!this.videoElement) {
      this.erstelleVideoElement();
    }

    const video = this.videoElement;
    if (!video) return false;

    try {
      const playPromise = video.play();
      if (playPromise !== undefined) {
        await playPromise;
      }
      this.videoAktiv = true;
      return true;
    } catch (err) {
      // Autoplay-Policy auf iOS erfordert noch eine Nutzerberührung
      this.videoAktiv = false;
      return false;
    }
  }

  private stoppeVideo(): void {
    if (this.videoElement) {
      try {
        this.videoElement.pause();
      } catch {}
      this.videoAktiv = false;
    }
  }

  private erstelleVideoElement(): void {
    const video = document.createElement("video");
    video.setAttribute("title", "HUNTING Wachhalter");
    video.setAttribute("aria-hidden", "true");

    // Unverzichtbare Attribute für iOS Safari Inline-Autoplay
    video.setAttribute("playsinline", "");
    video.setAttribute("webkit-playsinline", "");
    video.setAttribute("muted", "");
    video.muted = true;
    video.defaultMuted = true;
    video.setAttribute("loop", "");
    video.loop = true;
    video.setAttribute("autoplay", "");

    // 1x1 Pixel, transparent, unberührbar, außerhalb des sichtbaren Bereichs
    // Niemals display:none verwenden, da WebKit sonst das Decoding stoppt!
    Object.assign(video.style, {
      position: "fixed",
      top: "-20px",
      left: "-20px",
      width: "1px",
      height: "1px",
      opacity: "0.001",
      pointerEvents: "none",
      zIndex: "-9999",
    });

    // Quellen: WebM für Android/Desktop, MP4 (H.264) für iOS/Safari
    const sourceWebm = document.createElement("source");
    sourceWebm.src = WEBM_DATA_URI;
    sourceWebm.type = "video/webm";
    video.appendChild(sourceWebm);

    const sourceMp4 = document.createElement("source");
    sourceMp4.src = MP4_DATA_URI;
    sourceMp4.type = "video/mp4";
    video.appendChild(sourceMp4);

    // Endlos-Sicherheitsnetz bei Video-Ende
    video.addEventListener("ended", () => {
      if (this.istAktiv) {
        video.play().catch(() => {});
      }
    });

    // Zeit-Update-Trick: Setzt winzigen Loop zurück, verhindert Render-Hänger
    video.addEventListener("timeupdate", () => {
      if (video.currentTime > 0.5) {
        video.currentTime = Math.random() * 0.05;
      }
    });

    video.addEventListener("playing", () => {
      this.videoAktiv = true;
      this.benachrichtigeStatus();
    });

    video.addEventListener("pause", () => {
      if (this.istAktiv && document.visibilityState === "visible") {
        video.play().catch(() => {});
      } else {
        this.videoAktiv = false;
        this.benachrichtigeStatus();
      }
    });

    if (document.body) {
      document.body.appendChild(video);
    } else {
      document.addEventListener("DOMContentLoaded", () => {
        document.body.appendChild(video);
      }, { once: true });
    }

    this.videoElement = video;
  }

  /**
   * Automatisches Entsperren über die erste Touch-/Klick-Geste
   * (Überwindet die strenge iOS-Autoplay-Sperre sofort)
   */
  private gesteHandler = () => {
    if (this.istAktiv) {
      if (!this.videoAktiv) {
        this.starteVideo().catch(() => {});
      }
      if (this.wakeLockUnterstuetzt && !this.wakeLockAktiv) {
        this.anfordernWakeLock().catch(() => {});
      }
    }
  };

  private initialisiereGestenEntsperrung(): void {
    if (this.gestureListenerGebunden || typeof window === "undefined") return;

    const ereignisse = ["touchstart", "touchend", "pointerdown", "click", "keydown"] as const;
    for (const typ of ereignisse) {
      window.addEventListener(typ, this.gesteHandler, { passive: true });
    }
    this.gestureListenerGebunden = true;
  }

  private entferneGestenEntsperrung(): void {
    if (!this.gestureListenerGebunden || typeof window === "undefined") return;

    const ereignisse = ["touchstart", "touchend", "pointerdown", "click", "keydown"] as const;
    for (const typ of ereignisse) {
      window.removeEventListener(typ, this.gesteHandler);
    }
    this.gestureListenerGebunden = false;
  }

  /**
   * Status-Abonnement für UI-Komponenten
   */
  public get status(): WachhalterStatus {
    return {
      istAktiv: this.istAktiv,
      wakeLockAktiv: this.wakeLockAktiv,
      videoAktiv: this.videoAktiv,
      wakeLockUnterstuetzt: this.wakeLockUnterstuetzt,
    };
  }

  public abonnieren(listener: WachhalterListener): () => void {
    this.statusListeners.add(listener);
    listener(this.status);
    return () => this.statusListeners.delete(listener);
  }

  private benachrichtigeStatus(): void {
    const s = this.status;
    for (const cb of this.statusListeners) {
      try {
        cb(s);
      } catch (err) {
        console.error("[HUNTING Wachhalter] Fehler in Status-Listener:", err);
      }
    }
  }
}

export const wachhalter = new Wachhalter();
